'use strict';

function deepFreeze(value) {
  if (!value || typeof value !== 'object' || Object.isFrozen(value)) return value;
  for (const key of Reflect.ownKeys(value)) deepFreeze(value[key]);
  return Object.freeze(value);
}

function ready(slug, label, sideEffectClass = 'read') {
  return {
    slug,
    actionLabel: label,
    sideEffectClass,
    presentationDisposition: 't1-ready',
    executionEnabled: true,
    invocable: true,
  };
}

function unavailable(slug, label) {
  return {
    slug,
    actionLabel: label,
    sideEffectClass: 'read',
    presentationDisposition: 'uat-needed',
    executionEnabled: false,
    invocable: false,
  };
}

function projection({
  generation,
  origin,
  appStem,
  service,
  displayName,
  pageNoun,
  genre,
  adapterId,
  rendererId,
}) {
  return {
    generation,
    exactOrigin: origin,
    service,
    appStem,
    profileId: `fixture-${appStem}-${genre}`,
    profileVersion: 'skopeo-fixture-v1',
    contextEpoch: generation + 100,
    url: `${origin}/fixture/${genre}`,
    app: { appStem, service, displayName, pageNoun },
    genre,
    adapterId,
    rendererId,
  };
}

function stableEvidence(origin, id, label) {
  return [
    { signal: 'exact-origin', value: origin },
    { signal: 'opaque-target-key', value: id },
    { signal: 'visible-label', value: label },
  ];
}

function row({
  id,
  projection: exactProjection,
  requestedLens,
  adapterEvidence,
  readyCapabilities,
  nonReadyCapabilities,
  risk,
  entity,
  expectedAttention,
  expectedPrimitives,
  typedResult,
  expectedAtoms,
  expectedCopy,
}) {
  return {
    id,
    genre: exactProjection.genre,
    adapterId: exactProjection.adapterId,
    rendererId: exactProjection.rendererId,
    evidenceState: 'automated-fixture',
    liveApproval: 'not-live-approved',
    projection: exactProjection,
    requestedLens,
    adapterEvidence,
    readyCapabilities,
    nonReadyCapabilities,
    risk,
    entity,
    typedResult,
    expected: {
      firstAttention: expectedAttention,
      firstPrimitives: expectedPrimitives,
      atoms: expectedAtoms,
      copy: expectedCopy,
      normalWidth: {
        width: 1024,
        tableMode: expectedAtoms.includes('compact-table') ? 'compact-table' : 'not-applicable',
      },
      narrow: {
        width: 479,
        tableMode: expectedAtoms.includes('compact-table') ? 'fact-list' : 'not-applicable',
      },
      withdrawal: {
        attention: 'ambient',
        semanticEntity: null,
        anchorDescriptor: null,
        copy: `Skopeo can’t verify this ${exactProjection.app.pageNoun} anymore. Entity actions were removed.`,
      },
      off: {
        shellPresent: false,
        primitives: [],
        ownedResourceTotal: 0,
      },
    },
  };
}

